import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] p = new long[n];
        for (int i = 0; i < n; i++) p[i] = sc.nextLong();
        String t = sc.next();
        long score = 0;
        for (int i = 0; i < n; i++) {
            if (t.charAt(i) != 'T') continue;
            score += p[i];
            if (i > 0 && t.charAt(i - 1) == 'T') score++; // one bonus per adjacent T-T pair
        }
        System.out.println(score);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	p := make([]int64, n)
	for i := range p {
		fmt.Fscan(in, &p[i])
	}
	var t string
	fmt.Fscan(in, &t)
	var score int64
	for i := 0; i < n; i++ {
		if t[i] != 'T' {
			continue
		}
		score += p[i]
		if i > 0 && t[i-1] == 'T' { // one bonus per adjacent T-T pair
			score++
		}
	}
	fmt.Println(score)
}
